// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 depositAmount) public {
        vm.assume(depositor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 2); // avoid reverts from insufficient ETH

        uint256 snapBefore = address(c).balance;

        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        uint256 snapAfter = address(c).balance;

        assertTrue(snapAfter == snapBefore + depositAmount);
    }
}

