pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep depositor within admissible range excluding zero address to avoid confusion with creator
        vm.assume(depositor != address(0));
        // Fund depositor with enough Ether to cover the deposit plus a small buffer for gas
        vm.deal(depositor, amount + 1 ether);
        // Record balance before deposit
        uint256 prevBalance = c.balances(depositor);
        // Perform deposit as depositor
        vm.prank(depositor);
        c.deposit{value: amount}();
        // After deposit, the balance should strictly increase by the deposited amount
        uint256 newBalance = c.balances(depositor);
        assertTrue(newBalance == prevBalance + amount);
    }
}

