// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount1, uint256 depositAmount2) public {
        // The rule: the contract's ETH balance must equal the sum of all individual balances.
        // For two deposits by different users, after both deposits settle,
        // address(c).balance == c.balances(user1) + c.balances(user2) must always hold.
        // The bug reduces a user's balance instead of increasing it, breaking this invariant.

        address user1 = makeAddr("user1");
        address user2 = makeAddr("user2");

        // Bound values to prevent overflow and keep operations feasible
        uint256 maxDeposit = address(c).balance > type(uint128).max ? type(uint128).max : type(uint256).max;
        depositAmount1 = bound(depositAmount1, 1, type(uint128).max);
        depositAmount2 = bound(depositAmount2, 1, type(uint128).max);

        // Fund users
        vm.deal(user1, depositAmount1);
        vm.deal(user2, depositAmount2);

        // User1 deposits
        vm.prank(user1);
        c.deposit{value: depositAmount1}();

        // User2 deposits
        vm.prank(user2);
        c.deposit{value: depositAmount2}();

        // Assert invariant: contract ETH balance equals sum of all recorded balances
        uint256 sumBalances = c.balances(user1) + c.balances(user2);
        assertTrue(address(c).balance == sumBalances);
    }
}

