pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2) public {
        // Bound amounts to avoid overflow and ensure they are positive
        amount1 = bound(amount1, 1, 1 ether);
        amount2 = bound(amount2, 1, 1 ether);
        // Ensure actors are distinct and not the zero address
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != actor2);

        // Fund actors
        vm.deal(actor1, amount1 + amount2);
        vm.deal(actor2, amount2);

        // Actor1 deposits
        vm.prank(actor1);
        c.deposit{value: amount1}();

        // Actor2 deposits
        vm.prank(actor2);
        c.deposit{value: amount2}();

        // Actor2 refunds
        vm.prank(actor2);
        c.refund();

        // Actor1 refunds
        vm.prank(actor1);
        c.refund();

        // After all operations, the contract should have zero balance and all recorded balances should be zero
        assertEq(address(c).balance, 0);
    }
}

