pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        // Restrict to admissible domain: caller is a normal address, depositAmount > 0 to have something to withdraw, withdrawAmount > 0 to attempt a real withdrawal
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        depositAmount = bound(depositAmount, 1, type(uint256).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Setup: fund caller, deposit into contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Attempt withdrawal
        bool success;
        vm.prank(caller);
        try c.withdraw(withdrawAmount) {
            success = true;
        } catch {
            success = false;
        }

        // The reference C satisfies: if the withdrawal succeeds, the caller's balance after is strictly less than before.
        // The buggy M fails this because for withdrawAmount == balanceBefore, the withdrawal reverts, so success is false,
        // but the reference succeeds and reduces the balance. The assertion checks: if success is true, then balance after < balance before.
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter < balanceBefore);
        } else {
            // If withdrawal fails, this case doesn't violate the property (the property only speaks about successful withdrawals).
            // The bug will be found when the fuzzer picks withdrawAmount == balanceBefore: reference succeeds (balanceAfter=0 < balanceBefore),
            // buggy reverts (success=false, assertion skipped). The failing test condition is that the buggy contract yields a different success/fail pattern,
            // which this assertion doesn't directly catch. We need a property that the reference ALWAYS satisfies and the bug ALWAYS violates for some input.
            // Revised: For the reference, when withdrawAmount == balanceBefore, success is true. For the bug, success is false.
            // So the property: "if amount equals balanceBefore, the withdrawal must succeed".
            if (withdrawAmount == balanceBefore) {
                assertTrue(success);
            }
        }
    }
}

