pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address to, uint256 fundAmount) public {
        // Restrict to reasonable amount to avoid overflow, keep domain wide
        vm.assume(fundAmount <= address(this).balance / 2);
        vm.assume(caller != address(c));
        vm.assume(to != address(c));

        // Fund the contract so migrateTo has something to transfer
        vm.deal(caller, fundAmount);
        vm.prank(caller);
        c.deposit{value: fundAmount}();

        // Deploy a minimal proxy contract that forwards migrateTo call
        Forwarder forwarder = new Forwarder();

        // Make the call through forwarder, using the test contract as the proxy's deployer/caller
        vm.prank(caller);
        forwarder.forward(address(c), abi.encodeWithSelector(c.migrateTo.selector, to));

        // Assert: after migrateTo, contract balance must be zero if and only if caller == original creator.
        // The reference uses msg.sender (Forwarder address) so tx.origin check in buggy version
        // will treat caller as creator if caller is the original creator, while reference always rejects.
        address creator = address(uint160(uint256(keccak256(abi.encodePacked(address(this), address(c)))))); // dummy, we need a real creator
        // Better: get actual creator from contract setup. Since we deployed via setUp, this test contract is creator.
        // Actually, setUp deploys c, so this contract is creator.
        bool isCreator = (caller == address(this));
        uint256 bal = address(c).balance;
        // If caller is creator, reference rejects (msg.sender is Forwarder != this),
        // buggy accepts (tx.origin == caller == this). So balance depleted only if buggy and isCreator.
        // General invariant: balance == 0 implies creator called through forwarder (which bugs allows).
        // We assert: balance != 0 || (caller == address(this) && forwarder was used? No, just balance check.
        // Simpler: after call, if balance > 0, call must have reverted; if balance == 0, call succeeded.
        // Reference: call always reverts (msg.sender != creator). Bug: succeeds when tx.origin == creator.
        // So for reference, balance must always be fundAmount (unchanged). For buggy, balance 0 possible.
        // Therefore rule: balance == fundAmount (deposit untouched) for ALL inputs under reference.
        // Bug breaks: balance == 0 when caller == creator.
        assertTrue(bal == fundAmount, "Reference: migrateTo never succeeds from non-creator msg.sender");
    }
}

// Minimal forwarder contract to make tx.origin != msg.sender
contract Forwarder {
    function forward(address target, bytes memory data) external payable returns (bytes memory) {
        (bool ok, bytes memory result) = target.call(data);
        if (!ok) {
            assembly { revert(add(result, 32), mload(result)) }
        }
        return result;
    }
}

