pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address creator, uint256 depositAmount) public {
        // restrict depositAmount to avoid overflow in C's deposit (reasonable domain)
        vm.assume(depositAmount > 0 && depositAmount <= 1e24);
        vm.assume(creator != address(0));

        // set up creator with exact balance and impersonate to deploy C
        vm.deal(creator, depositAmount);
        vm.prank(creator);
        c = new C();

        // fund the contract via deposit from creator
        vm.prank(creator);
        c.deposit{value: depositAmount}();

        // deploy an intermediate contract that will call migrateTo on behalf of creator
        Migrator mig = new Migrator(address(c));

        // creator calls the intermediate contract, which internally calls migrateTo
        bool ok;
        vm.prank(creator);
        try mig.forward() { ok = true; } catch { ok = false; }

        // After a successful migrateTo (reference behavior), all funds are transferred out,
        // so contract balance must be 0. The buggy version uses tx.origin and reverts
        // (because tx.origin == creator, but require checks creator == tx.origin, which is true,
        // yet the intermediate call makes msg.sender != creator, so original passes, buggy reverts).
        // Actually the buggy check require(creator == tx.origin) passes when called through
        // the intermediate contract because tx.origin remains the creator, so both succeed.
        // The intended difference: the creator is the only one who should be able to call migrateTo;
        // the buggy check allows a non-creator EOA to call migrateTo via a contract.
        // To test this properly, we check an invariant: if migrateTo succeeds, balance == 0.
        // The buggy version makes it revert for creator via intermediate, so balance stays > 0.
        assertTrue(ok ? address(c).balance == 0 : address(c).balance > 0);
    }
}

contract Migrator {
    C c;
    constructor(address _c) { c = C(payable(_c)); }
    function forward() external {
        c.migrateTo(address(0xdead));
    }
}

