        // seed funds: deposit into contract from creator (or any address)
        address depositor = address(uint160(uint256(keccak256(abi.encode(seed, "dep")))));
        vm.assume(depositor != address(0));
        uint256 depositAmount = 1 ether + (seed % 100 ether);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "setup: balance must be >0");

