        address to = address(uint160(uint256(keccak256(abi.encode(seed, "to")))));
        vm.assume(to != address(c));
        vm.prank(caller);
        try c.migrateTo(to) {} catch {}

        uint256 balanceAfter = address(c).balance;

        // Property: after migrateTo, the contract's balance must be 0
        // The reference requires creator == msg.sender, so non-creator callers revert and balance stays put.
        // The buggy version allows anyone to succeed, draining balance to 0.
        // For creator callers, both succeed and balance becomes 0.
        // For non-creator callers, reference reverts (balance unchanged), bug drains.
        // Hence property holds for reference: if caller is creator, balance=0 (true); if not, balanceBefore=balanceAfter (which may be >0).
        // Actually we need a property that holds for ALL inputs for reference, but fails for bug. "Balance must be 0 after call" fails for reference when non-creator calls, because balance stays >0. So that's not valid.
        // The correct property: After any call to migrateTo, the balance is either the original balance (reverted) or 0 (succeeded). The sum over all actors: for reference, only creator can succeed -> balance 0 for creator, unchanged for others. For bug, anyone can succeed -> balance 0 for all. The distinguishing property: the balance after call is 0 iff the caller is the creator. That's not a general property of the contract itself?
